module.TargetCode:
void Move(string key)
{
    if (key == "w")
    {
        playerY--;
    }
    else if (key == "s")
    {
        playerY++;
    }
    else if (key == "a")
    {
        playerX--;
    }
    else if (key == "d")
    {
        playerX++;
    }
}

